select * from (
    select A.*,M.MACHINE_NAME from t_nc_quota_setting A LEFT JOIN T_NC_MACHINE_INFO M
    ON A.machine_id=M.ID
    WHERE A.del_flag='0'
    and A.lining_code = #{liningCode}
    and A.machine_id = #{machineId}

        ORDER BY A.create_time desc

) t

    order by ${orderStr}

