lining_code = #{liningCode,jdbcType=VARCHAR}, machine_id = #{machineId,jdbcType=DECIMAL}, quota = #{quota,jdbcType=DECIMAL}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, remark = #{remark,jdbcType=VARCHAR},
where id = #{id}

